  function coast(island,scale,depth,y,color){const shape=new THREE.Shape();A.coast(island).forEach((p,i)=>{const x=(island.x+(p.x-island.x)*scale)*.1,z=(island.y+(p.y-island.y)*scale)*.1;i?shape.lineTo(x,-z):shape.moveTo(x,-z);});shape.closePath();const geometry=geom(new THREE.ExtrudeGeometry(shape,{depth,bevelEnabled:false,steps:1}));geometry.rotateX(-Math.PI/2);const mesh=new THREE.Mesh(geometry,mat(color));mesh.position.y=y;mesh.receiveShadow=true;scene.add(mesh);}
