    const h=new THREE.Mesh(geom(new THREE.RingGeometry(7.5,7.85,20)),new THREE.MeshBasicMaterial({color:P.gold,transparent:true,opacity:.75,side:THREE.DoubleSide,depthWrite:false}));h.rotation.x=-Math.PI/2;h.scale.y=.6;h.position.set(x,ground+.1,z);h.visible=false;h.userData.noMerge=true;parent.add(h);halos.set(team.id,h);materials.set('halo-'+team.id,h.material);
